#include <stdio.h>
#include <stdlib.h>

/* Maximum n allowed (as observed in the binary) */
#define MAX_N 60

static long memo[MAX_N + 1][MAX_N + 1];
static char computed[MAX_N + 1][MAX_N + 1];

/* Recursive binomial coefficient with memoisation */
static long binom(int n, int k)
{
    /* Base cases */
    if (k == 0 || k == n)
        return 1;
    if (n < k)
        return 0;
    if (k < 0)
        return 0;

    if (computed[n][k])
        return memo[n][k];

    long v = binom(n - 1, k - 1) + binom(n - 1, k);
    memo[n][k] = v;
    computed[n][k] = 1;
    return v;
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1 = NULL, *end2 = NULL;
    long n = strtol(argv[1], &end1, 10);
    long k = strtol(argv[2], &end2, 10);

    /* Validate that both arguments are proper integers */
    if (end1 == argv[1] || *end1 != '\0' ||
        end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Range check – the original program only supports 0 <= n <= 60 */
    if (n < 0 || n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    long result = binom((int)n, (int)k);
    printf("%lld\n", result);
    return 0;
}
